import { type } from "arktype";

const Response = type({
    status: "number.integer >= 100 <= 599",
    body: "string"
});

const Params = type({
    url: "string.url",
    timeoutMs: "number.integer > 0 <= 10000",
    retries: "number.integer >= 0 <= 5"
});

const PromiseReturn = type.instanceOf(Promise);

export const fetchWithTimeout = type.fn(
    Params,
    ":",
    PromiseReturn
)(
    async (params) => {
        const delay = Math.min(params.timeoutMs, 50);
        const result = await new Promise<{ status: number; body: string }>((resolve) => {
            setTimeout(() => resolve({ status: 200, body: "ok" }), delay);
        });
        return Response.assert(result);
    }
);

async function main() {
    // valid
    try {
        const r = await fetchWithTimeout({ url: "https://example.com", timeoutMs: 100, retries: 2 });
        console.log("valid result:", JSON.stringify(r));
    } catch (e) {
        console.log("valid ERR:", String((e as Error).message).split("\n")[0]);
    }

    // invalid param (bad url) - should throw synchronously
    try {
        const r = await fetchWithTimeout({ url: "not-a-url", timeoutMs: 100, retries: 2 });
        console.log("badurl result:", JSON.stringify(r));
    } catch (e) {
        console.log("badurl ERR:", String((e as Error).message).split("\n")[0]);
    }

    // invalid param (timeoutMs 0)
    try {
        const r = await fetchWithTimeout({ url: "https://example.com", timeoutMs: 0, retries: 2 });
        console.log("zero result:", JSON.stringify(r));
    } catch (e) {
        console.log("zero ERR:", String((e as Error).message).split("\n")[0]);
    }

    // invalid retries
    try {
        const r = await fetchWithTimeout({ url: "https://example.com", timeoutMs: 100, retries: 6 });
        console.log("retries result:", JSON.stringify(r));
    } catch (e) {
        console.log("retries ERR:", String((e as Error).message).split("\n")[0]);
    }
}

