	const start = Date.now();
	try {
		await fetchWithTimeout({ url: "bad", timeoutMs: 5000, retries: 2 } as never);
	} catch (e) {
		const elapsed = Date.now() - start;
		console.log("invalid param threw, elapsed:", elapsed, "ms (<50 means synchronous, no timer)");
		console.log("err:", (e as Error).message.split("\n")[0]);
	}
}

void main();
